INSERT INTO `hints` (`tid`, `text`) VALUES ('books_dtConfederates','Это количество конфедерат. Единственная валюта принятая для торговли редкими артефактами.'),('books_dtCredits','Это количество кредитов. Кредиты это общегалактическая валюта для торговли. Принимается всеми торговыми станциями.'),('books_dtDefence','В случае нападения конфедерация оценивает ваши силы и силы противника и при перевесе в сторону противника высылает свой флот на помощь вам.'),('books_dtHomePlanet','Это планета которая была выбрана для колонизации. Конфедерация возлагает надежды на вас, как колонизатора.'),('books_dtHomeStar','Это ваша звезда. Именно тут вас высадили корабли конфедерации. Вы можете переименовать звезду если пожелаете.'),('books_dtInsur','Наличие и количество страховок. Используется для сохранения имплантантов в случае смерти.'),('books_dtLevel','Это общий уровень, который показывает некоторую статистику вашей деятельности. Чем выше уровень, тем большего вы добились.'),('books_dtLink','Позволяет вам пополнить счет конфедератами. Курс перевода очень зависит от способа пополнения.'),('books_dtNewName','Вам необходимо выбрать новое имя. Имя должно быть уникально и не содержать оскорблений или унижений.'),('books_dtOrbitAtack','Общая сила атаки с орбиты. Орбита это первая линия обороны, чем больше это число тем большие потери понесет противник в случае нападения.'),('books_dtOrbitBuildings','Количество орбитальных построек. Максимальное количество построек 50. Учитывая это можно оценить занятость орбиты ее развитость.'),('books_dtOrbitShield','Общая сила щитов орбиты. Вычисляется путем сложения щита каждой отдельной конструкции, на орбите щит не закрывает не военные постройки и они могут быть уничтожены.'),('books_dtOrbitShips','Количество кораблей дислоцирующихся на орбите. Позволяет примерно оценить флот орбитальной обороны.'),('books_dtOrbitWare','Орбитальный склад. Отображается именно <u>свободное</u> место на орбите. Как и на планете все склады связаны между собой и представляются единым складом.'),('books_dtPlanet','Планета, где вы сейчас находитесь. Это местоположение непосредственно вас, как космонавта.'),('books_dtPlanetAtack','Суммарна сила залпа всех планетарных военных построек. Позволяет оценить обороноспособность планеты. Чем выше число, тем больший флот может быть уничтожен.'),('books_dtPlanetBuildings','Количество построек на планете. Позволяет оценить ресурс планеты. Чем больше построек, тем меньше свободного места. Так же является показателем развитости колонии.'),('books_dtPlanetShield','Общая сила щитов. Чем больше щитов размещено на поверхности планеты, тем дольше продержаться войска во время атаки. Щиты помогают выиграть битву за планету.'),('books_dtPlanetShips','Количество кораблей на планете. Учитываются только расконсервированные корабли. Позволяет оценить флот дислоцирующийся на планете.'),('books_dtPlanetWare','Общий склад планеты. Позволяет оценить возможности хранения товара. Отображается именно <u>свободное</u> место на планете'),('books_dtReferal','Если вы дадите эту ссылку вашим друзьям, то они могут принести вам прибыль. Все операции связанные с конфедератами принесут вам 10%25 в том числе окончание обучения.'),('books_dtRename','Вы можете задать свое имя для планеты или звезды. Это платная услуга, поскольку потребуется регистрация во всех справочниках галактики.'),('books_dtRobots','Количество роботов которые находятся в вашем подчинении. Роботы в данном случае не разделяются по типам.'),('books_dtStar','Звезда, где вы сейчас находитесь. Это местоположение непосредственно вас, как космонавта.'),('books_dtStatus','Это показатель ваших отношений с конфедерацией. При отрицательном значении вы станете пиратом.'),('books_dtWar','Тут отражается ваш уровень военного мастерства. Он увеличивается, когда вы выигрываете битву. Уменьшается в случае вашего проигрыша.'),('books_instance1','Левая панель где выводится информация о вас. Тут можно узнать ваше местоположение, а так же посмотреть основные характеристики.'),('books_instance138','Позволяет перейти к игроку, что бы посмотреть информацию о нем, поменять отношение к нему или назначить вознаграждение за его голову.'),('books_instance182','Запускает все добывающие сооружения на максимально возможное количество циклов. Отчет приходит в системном чате.'),('books_instance195','Запускает все доступные нанодиспенсеры на планете на переработку руды. Все детали и корабли остаются в исходном состоянии.'),('books_instance208','Запускает все нанодиспенсеры используя любое сырье. Это может быть руда, детали, корабли. В итоге разбирая все до элементов.'),('books_instance221','Позволяет переименовать звезду или планету недопустимо использование оскорбляющих слов и выражений.'),('books_instance23','Панель отношений позволяет определить кто из пилотов является вашим другом или врагом, а так же кому вы друг или враг.'),('books_instance25','Панель отношений позволяет определить кто из пилотов является вашим другом или врагом, а так же кому вы друг или враг.'),('books_instance283','Запускает выполнение задания. После вашего согласия задание уйдет из общего списка. Помните, что от некоторых заданий вы не сможете отказаться.'),('books_instance296','Позволяет отказаться от трудного или невыполнимого задания. После вашего отказа конфедерация понизит ваш статус и несколько минут вы не сможете выполнять задания.'),('books_instance3','Левая панель где выводится информация о вас. Тут можно узнать ваше местоположение, а так же посмотреть основные характеристики.'),('books_instance30','Панель статистики позволяет рассмотреть общие сведения о вашей звездной системе, а так же контролировать ваши колонии.'),('books_instance32','Панель статистики позволяет рассмотреть общие сведения о вашей звездной системе, а так же контролировать ваши колонии.'),('books_instance345','Отдает команду на изучение. Развитие ваших навыков улучшает тот или иной показатель. Все навыки полезны, однако следует определить очередность вашего обучения.'),('books_instance381','Позволяет удалить выбранные сообщения в независимости от их важности и прочитанности. Можно выделить все сообщения и затем удалить этой кнопкой.'),('books_instance394','Позволяет удалить все прочитанные сообщения одним нажатием. Так же удалятся маловажные сообщения.'),('books_instance420','Позволяет написать сообщение любому игроку. После того как он появится в эфире сообщение будет доставлено.'),('books_instance46','Панель заданий. Позволяет выполнять небольшие миссии от конфедерации. За выполнение заданий выплачивается вознаграждение, а так же улучшается статус.'),('books_instance48','Панель заданий. Позволяет выполнять небольшие миссии от конфедерации. За выполнение заданий выплачивается вознаграждение, а так же улучшается статус.'),('books_instance509','Ярко зеленый цвет обозначает взаимно дружественные отношения. Темно зеленый - вы считаете его другом. Нейтральный - вас считают другом.'),('books_instance53','Панель обучения. Тут вы можете изучать науки, развиваться и устанавливать имплантанты. Все это значительно улучшает ваши возможности.'),('books_instance537','Ярко красный цвет обозначает взаимно враждебные отношения. Темно красный - вы считаете его врагом. Нейтральный - вас считают врагом.'),('books_instance55','Панель обучения. Тут вы можете изучать науки, развиваться и устанавливать имплантанты. Все это значительно улучшает ваши возможности.'),('books_instance565','Список ваших колоний. На первом месте всегда стоит ваша родная система, затем родная планета, затем все колонии.'),('books_instance60','Имплантант это зачастую микрокомпьютер интегрируемый в мозг. Иногда биокомпьютер. Имплантант позволяет значительно расширить способности организма.'),('books_instance61','Панель сообщений. Тут выводятся все сообщения, которые были присланы вам системой или другими пилотами. Вы так же можете ответить или написать свое сообщение.'),('books_instance62','Панель сообщений. Тут выводятся все сообщения, которые были присланы вам системой или другими пилотами. Вы так же можете ответить или написать свое сообщение.'),('books_instance683','Список присланных сообщейний. Слева отображается отправитель, справа краткий текст сообщения. Выделив сообщение можно прочесть его полностью.'),('misc_dtDesc','Подробное описание объекта. Энциклопедия позволяет вспомнить то, что вы учили в академии дальней разведки. Это наиболее полный источник ваших знаний.'),('misc_instance148','Сохраняет все выбранные настройки. Громкость музыки изменится через некоторое время после сохранения.'),('misc_instance290','Список ваших роботов. Роботы часто используются на производствах для ускорения процесса. Приобрести их можно у конфедерации в любом количестве.'),('misc_instance3','Громкость проигрывания музыки. При громкости меньше 10%25 музыка при входе будет отключена.'),('misc_instance6','Громкость звуков и эффектов. При экономии траффика можно не трогать этот параметр, поскольку он никак не влияет.'),('misc_instance73','Громкость проигрывания музыки. При громкости меньше 10%25 музыка при входе будет отключена.'),('misc_instance74','Громкость проигрывания музыки. При громкости меньше 10%25 музыка при входе будет отключена.'),('misc_instance75','Громкость звуков и эффектов. При экономии траффика можно не трогать этот параметр, поскольку он никак не влияет.'),('misc_instance76','Громкость звуков и эффектов. При экономии траффика можно не трогать этот параметр, поскольку он никак не влияет.'),('orbit_dtCbHeader','Основная характеристика объекта.'),('orbit_dtCoord','Координаты выбранного объекта. Всего орбита содержит 50 точек стояния. В каждой точке можно расположить 1 орбитальную постройку.'),('orbit_dtCount','Количество производственных циклов.'),('orbit_dtDesc','Описание выбранной постройки. Основное назначение и некоторые характеристики.'),('orbit_dtDgHeader','Пояснение к таблице. Как правило тут приводится время производства или информация об орбите в целом.'),('orbit_dtLevel','Уровень постройки. Большинство построек можно улучшить до 10 уровня. Это увеличивает эффективность использования точки стояния.'),('orbit_dtTitle','Наименование и уровень выбранной постройки. Большинство построек можно улучить, это позволяет эффективней использовать пространство орбиты.'),('orbit_instance11','Панель улучшения. Позволяет улучшить орбитальную постройку за счет доработок и технологических улучшений.'),('orbit_instance114','Запускает улучшение. Помните, что улучшение нельзя будет остановить или отменить и постройки может оказаться недоступной на время улучшения.'),('orbit_instance125','Панель улучшения. Позволяет улучшить орбитальную постройку за счет доработок и технологических улучшений.'),('orbit_instance13','Панель использования. Позволяет производить основные операции с постройками. Это основная панель управления.'),('orbit_instance145','Выпадающий список с выбором производимого действия. Многие объекты умеют только хранить ресурсы.'),('orbit_instance171','Запускает производство, переработку или добычу с использованием робота. Это позволяет использовать постройку максимально эффективно.'),('orbit_instance184','Запускает выбранное действие на орбитальной постройке. Большинство действий можно отменить.'),('orbit_instance20','Количество производственных циклов.'),('orbit_instance22','Панель использования. Позволяет производить основные операции с постройками. Это основная панель управления.'),('orbit_instance24','Информационная панель. Позволяет посмотреть название и характеристики орбитальных построек, а так же снести их.'),('orbit_instance266','Прерывает ранее запущенное действие. Учтите, что прерванный цикл не завершится и все вернется в состояние начала цикла.'),('orbit_instance27','Координаты выбранного объекта. Всего орбита содержит 50 точек стояния. В каждой точке можно расположить 1 орбитальную постройку.'),('orbit_instance277','Панель использования. Позволяет производить основные операции с постройками. Это основная панель управления.'),('orbit_instance29','Информационная панель. Позволяет посмотреть название и характеристики орбитальных построек, а так же снести их.'),('orbit_instance294','Позволяет уничтожить постройку. После сноса вам вернут половину ресурсов затраченных на постройку и все улучшения.'),('orbit_instance305','Информационная панель. Позволяет посмотреть название и характеристики орбитальных построек, а так же снести их.'),('orbit_instance326','Подтверждает приказ о сносе. Помните, что это действие является необратимым и его нельзя будет отменить позднее. В случае ошибки придется строить заново.'),('orbit_instance339','Отменяет приказ о сносе орбитальной постройки.'),('orbit_instance370','Список ресурсов необходимый для улучшения. Красным отмечены недостающие ресурсы.'),('orbit_instance394','В зависимости от выбранной постройки тут выводятся разные сведения. Как правило это ресурсы или детали и их количество.'),('orbit_instance5','Панель улучшения. Позволяет улучшить орбитальную постройку за счет доработок и технологических улучшений.'),('orbit_instance516','Это планета на орбите которой вы находитесь.'),('planet_dtCbHeader','Основная характеристика объекта.'),('planet_dtCoord','Координаты выбранного объекта. Во многих случаях система сообщает именно эти координаты, что бы однозначно идентифицировать постройку.'),('planet_dtCount','Количество производственных циклов.'),('planet_dtDesc','Описание выбранной постройки. Основное назначение и некоторые характеристики.'),('planet_dtDgHeader','Пояснение к таблице. Как правило тут приводится время производства или информация о планете в целом.'),('planet_dtLevel','Уровень постройки. Большинство построек можно улучшить до 10 уровня. Это увеличивает эффективность использования точки стояния.'),('planet_dtTitle','Наименование и уровень выбранной постройки. Большинство построек можно улучить, это позволяет эффективней использовать пространство планеты.'),('planet_instance12','Панель улучшения. Позволяет улучшить планетарную постройку за счет доработок и технологических улучшений.'),('planet_instance135','Запускает улучшение. Помните, что улучшение нельзя будет остановить или отменить и постройки может оказаться недоступной на время улучшения.'),('planet_instance14','Панель использования. Позволяет производить основные операции с постройками. Это основная панель управления.'),('planet_instance146','Панель улучшения. Позволяет улучшить планетарную постройку за счет доработок и технологических улучшений.'),('planet_instance166','Выпадающий список с выбором производимого действия. Многие объекты умеют только хранить ресурсы.'),('planet_instance192','Запускает выбранное действие на планетарной постройке. Большинство действий можно отменить.'),('planet_instance205','Запускает производство или добычу с использованием робота. Это позволяет использовать постройку максимально эффективно.'),('planet_instance21','Количество производственных циклов.'),('planet_instance23','Панель использования. Позволяет производить основные операции с постройками. Это основная панель управления.'),('planet_instance241','Уменьшить количество циклов на 1.'),('planet_instance25','Информационная панель. Позволяет посмотреть название и характеристики планетарных построек, а так же снести их.'),('planet_instance253','Увеличить количество циклов на 1.'),('planet_instance265','Установить минимальное количество циклов.'),('planet_instance277','Установить максимально возможное количество циклов.'),('planet_instance28','Координаты выбранного объекта. Во многих случаях система сообщает именно эти координаты, что бы однозначно идентифицировать постройку.'),('planet_instance298','Панель использования. Позволяет производить основные операции с постройками. Это основная панель управления.'),('planet_instance3','Панель управления миникартой. Кнопкой \"+\" можно выделить все объекты которые можно улучшить. Объекты выделятся красным цветом.'),('planet_instance30','Информационная панель. Позволяет посмотреть название и характеристики планетарных построек, а так же снести их.'),('planet_instance315','Позволяет уничтожить постройку. После сноса вам вернут половину ресурсов затраченных на постройку и все улучшения.'),('planet_instance326','Информационная панель. Позволяет посмотреть название и характеристики планетарных построек, а так же снести их.'),('planet_instance347','Подтверждает приказ о сносе. Помните, что это действие является необратимым и его нельзя будет отменить позднее. В случае ошибки придется строить заново.'),('planet_instance360','Отменяет приказ о сносе планетарной постройки.'),('planet_instance37','Миникарта. Позволяет оценить занятость планеты, быстро переместится к нужной руде или к простаивающему производству.'),('planet_instance390','Список ресурсов необходимый для улучшения. Красным отмечены недостающие ресурсы.'),('planet_instance414','В зависимости от выбранной постройки тут выводятся разные сведения. Как правило это ресурсы или детали и их количество.'),('planet_instance6','Панель улучшения. Позволяет улучшить планетарную постройку за счет доработок и технологических улучшений.'),('ships_dtCount','Количество кораблей которые вы хотите расконсервировать. При количестве больше 1 расконсервированные корабли объединяются во флот.'),('ships_dtGroup','Имя группы кораблей. При наличии имплантанта \"Модуль объединения\" позволяет фильтровать корабли и флота по группам.'),('ships_dtInfo','Характеристики выбранного корабля или флота. Тут вы можете увидеть владельца и технические характеристики. Позволяет оценивать противника.'),('ships_dtName','Имя корабля или флота. Запрещается использовать оскорбительные слова или выражения.'),('ships_dtShips','Список кораблей в флоте. Все корабли перечисленные в списке получают общий приказ и действуют совместно.'),('ships_instance106','Список ваших кораблей и флотов. Выбрав корабль вы можете отдать ему приказ.'),('ships_instance2180','Список всех товаров на корабле или всех кораблях флота. Как правило используется, что бы проверить заправлен ли корабль и насколько он снаряжен'),('ships_instance5612','Отдает приказ на переименование корабля или флота