INSERT INTO `tutorials` (`level`, `page_id`, `premium`, `tutorial`) VALUES (1,1,0,'1(34) Добро пожаловать!\n\nВы прошли обучение в \"Академии дальней разведки\" и теперь получили возможность колонизировать планету. В качестве отправной точки была найдена звездная система с планетой земного типа. Конфедерация планет гарантирует вам полную безопасность на этой планете. Однако никто не ограничивает вас в действиях, и вы имеете полное право колонизировать любые другие планеты. Конфедерация осуждает взаимное нападение, однако не вмешивается в боевые действия, за исключением случаев, когда объект находится под охраной конфедерации.\n\nНа начальном этапе вас будут сопровождать обучающие сообщения, от точного выполнения заданий зависит время, за которое вы адаптируетесь к новым условиям чужой планеты. По окончании обучения конфедерация выплатит вам 10 конфедерат.'),(2,1,0,'2(34) Вы находитесь в модуле управления обучением.\n\nК сожалению, дальний перелет невозможен без криокамеры, а это накладывает отпечаток на память. Все приобретенные знания забываются, однако благодаря технологии регенерации нейросетей есть возможность восстановить эти знания. Вам следует определить только последовательность восстановления знаний.\n\nКаждое знание, умение или навык дает новые возможности. Некоторые из них необходимы для производства или осуществления управления. Другие лишь ускоряют процессы. Чем выше уровень, тем труднее восстанавливать нейронные связи, поскольку восстановление общей картины ведется наведенными токами большой мощности. В то же время для восстановления деталей необходимы токи малой мощности, что увеличивает время обучения.\nОбучение нельзя прервать, поскольку часть мозга окажется заблокированной навсегда. Знания, полученные при обучении сразу отпечатываются в матрице регенерационной машины, что позволит в последующем восстанавливать тело и память одновременно.'),(3,2,0,'3(34) Вы находитесь в модуле управления окружающим пространством.\n\nВ настоящий момент вы находитесь на планете, на экране вы можете видеть поверхность планеты. В левом верхнем углу есть иконка \"мини карты\" если подвести к ней указатель раскроется карта, кликнув в любой точке на карте, вы быстро переместитесь в нужное место. Все постройки на карте отображаются яркой белой точкой, в то время как поверхность отображается соответствующим цветом.\nПервая постройка, которая есть на вашей планете это \"капсула\". Капсула представляет собой космический корабль, на котором вы прибыли на планету. Корабль снабжен устройством регенерации, что позволяет вам полностью восстанавливать тело и память после гибели. \nНа корабле есть минимальный запас минералов, который позволит вам начать развитие. Отнеситесь ответственно к первым шагам на планете, если вы неправильно распределите изначальные ресурсы вы, не сможете правильно начать развивать свою колонию.\n\nНа экране слева вы видите панель управления, состоящую из 3-х основных частей.\n<b>Информация</b> - в данной закладке отображается информация о точке на планете, а так же основные сведения о постройках. Из этой закладки в случае необходимости можно осуществить снос любого сооружения кроме капсулы.\n<b>Использование</b> - в данной закладке отображаются все возможные действия с выделенным объектом. Из этой закладки осуществляется строительство, запуск шахт карьеров, заводов и пр. Если постройка не несет в себе созидательной функции, в данной закладке отображаются все хранимые вещи.\n<b>Усовершенствовать</b> - в данной закладке отображаются возможность по усовершенствованию построек. Так же из этой закладки можно запустить исследования почвы (Необходим геологический зонд) что позволит добывать более редкие минералы.\n'),(4,2,500,'4(34) Электростанция.\n\nДля начала необходимо построить Электростанцию, это обеспечит вас энергией.\nВыберите свободное место на планете и перейдите в панель \"Использовать\".\nУстановите тип постройки \"Электростанция\" и начните строительство нажатием кнопки \"Начать строительство\".\n\nНа карте появится пустая платформа и таймер красного цвета. Цвет таймера зависит от события, стройка отображается красным цветом. Когда строительство будет завершено, на карте появится здание электростанции. Поскольку электростанция не несет в себе дополнительных функций, в закладке \"использование\" можно увидеть какие вещи присутствуют на планете, а так же количество доступной энергии.\n\n<i>Постройте электростанцию</i>\n<b>вознаграждение: 500</b>'),(5,2,500,'5(34) Нанодиспенсер\n\nТеперь, когда у вас есть электростанция, вы можете построить \"Нанодиспенсер\". Нанодиспенсер - позволяет перерабатывать сложные вещества или детали, разбирая их на атомарном уровне. В результате получаются чистые материалы. Существует минимально-необходимое количество материала для начала процесса, однако максимальное количество никак не ограничено. Время, которое затрачивается на выделение материалов, не зависит от количества сырья.\nДля постройки выберете любую свободную поверхность, зайдите в панели слева в закладку \"Использовать\" и выберите \"Нанодиспенсер\", начните строительство.\n\n<i>Постройте нанодиспенсер</i>\n<b>вознаграждение: 500</b>'),(6,2,0,'6(34) Энциклопедия\n\nПосле постройки нанодиспенсера можно начать разработку полезных ископаемых. Прежде всего, необходимо наладить добычу железа и кремния, так как это основные компоненты строительства. Для этого, нужно узнать в какой породе содержится достаточное количество этих минералов.\nТочные справочные сведения содержатся в Энциклопедии в закладке \"прочее\".\n\n<i>Перейдите в прочее, выберите энциклопедию</i>\n'),(7,6,0,'7(34) Железо\n\nТеперь необходимо найти минерал содержащий Железо.\nДля этого выберите слева \"Железо\" и, заходя в каждый минерал из описания справа, найдите минерал первой группы.\n\n<i>Найдите минерал 1-го слоя содержащий железо</i>\n'),(8,6,0,'8(34) Гематит\n\nГематит - как видно из описания это полезное ископаемое первой группы, соответственно добывать его можно используя карьер. Теперь можно вернуться на страницу \"Местность\" и начать разработку этого полезного ископаемого.'),(9,2,500,'9(34) Гематит\n\nДля начала разработки Гематита необходимо обнаружить его на планете, для этого на панели слева необходимо выбрать вкладку \"Информация\" и переходя по разным областям на планете найти область с Гематитом. Визуально поверхность представляет собой травянистую поляну.\n\nКак правило во время посадки капсула производит предварительную разведку поверхности и старается приземлится в центральной зоне гематита.\n\n<i>Найдите на поверхности Гематит</i>\n\n<b>вознаграждение: 500</b>'),(10,2,500,'10(34) Карьер\n\nГематит найден, можно приступать к его разработке.\nДля этого выберите в панели слева закладку \"Использовать\". В списке построек нам необходим \"карьер\". Постройте карьер в той точке, где был найден гематит.\n\n<i>Постройте карьер для добычи Гематита</i>\n\n<b>вознаграждение: 500</b>'),(11,2,1000,'11(34) Кремний\n\nТеперь необходимо позаботится о втором по необходимости материале - кремнии. Для этого в Энциклопедии нам необходимо найти кремний, а затем выбрать из полезных ископаемых ископаемое первого уровня, что бы можно было легко обнаружить его на поверхности.\n\n<i>Найдите полезное ископаемое первой группы в составе которого присутствует Кремний</i>\n\n<b>вознаграждение: 1000</b>'),(12,6,0,'12(34) Кварц.\n\nВы правильно нашли полезное ископаемое, которое необходимо. Как вы видите \"кварц\" находится на первом уровне, а соответственно его будет легко найти на планете. Внешне это ископаемое выглядит как желтый песок.'),(13,2,500,'13(34) Карьер\n\nКварц найден. Запомните как он выглядит, это позволит в будущем наращивать производственные мощности.\nТеперь необходимо начать его разработку, для этого в левой панели необходимо выбрать \"Использовать\", а затем тип постройки \"Карьер\" и запустить строительство.\n\n<i>Постройте карьер для добычи кварца</i>\n\n<b>вознаграждение: 500</b>'),(14,2,1000,'14(34) Запуск производства\n\nТеперь необходимо запустить карьеры. Для этого необходимо выделить карьер на карте, в левой панели перейти в закладку \"Использовать\" и запустить цикл.\nКоличество доступных циклов зависит от уровня карьера. Чем выше уровень карьера, тем больше циклов без перезапуска доступно. Для безостановочной добычи используйте роботов, это позволит добывать больше ресурсов не теряя времени на простой производства.\nВ независимости от количества запущенных циклов любой процесс производства можно прервать. Для увеличения уровня постройки необходимо выбрать пункт меню \"Усовершенствовать\" и запустить усовершенствование.\nКоличество добытых ископаемых можно посмотреть в нейтральных постройках, таких как Капсула, Электростанция или Склад. Вам необходимо добыть 100 единиц полезных ископаемых.\n\n<i>Запустите карьеры для добычи кварца и гематита необходимо добыть 100 кварца и 100 гематита</i>\n\n<b>вознаграждение: 1000</b>\n'),(15,2,1500,'15(34) Переработка\n\nКоличество добытых полезных ископаемых достигло уровня переработки. Теперь можно загрузить их в нанодиспенсер и переработать, что бы получить чистые минералы. Для этого выделите нанодиспенсер, а в левой панели выберите закладку \"Использовать\". В выпадающем списке будут все детали и полезные ископаемые, которые можно переработать.\nЧем выше уровень постройки, тем выше КПД, соответственно тем больше материалов получится из того же количества сырья. На первом уровне КПД 70%25\n\n<i>Переработайте полезные ископаемые в нанодиспенсере и получите элементы</i>\n\n<b>вознаграждение: 1500</b>\n'),(16,2,2000,'16(34) Титан\n\nТеперь вам предоставляется возможность самостоятельно найти и разработать новый материал. <b>Титан</b>. Он понадобится для производства геологических зондов.\n\nТитан является распространенным материалом, однако до изобретения наноботов его было очень трудно перерабатывать из-за его высокой температуры плавления и большой прочности. В настоящее время Титан используется повсеместно, раньше эту нишу производства занимал алюминий и его сплавы с магнием.\n\n<i>Найдите в энциклопедии полезное ископаемое первой группы в состав которого входит титан, установите карьер, добудьте и переработайте полученные полезные ископаемые, что бы получить титан.</i>\n\n<b>вознаграждение: 2000</b>\n'),(17,2,1000,'17(34) Завод\n\nВы самостоятельно нашли, добыли и переработали полезные ископаемые и получили Титан. Теперь необходимо начать производство. Для этого найдите пустое место на поверхности и постройте \"Завод\".\n\n<i>Постройте завод на пустой точке поверхности</i>\n\n<b>вознаграждение: 1000</b>'),(18,2,2000,'18(34) Геологический зонд.\n\nДля работы заводу необходимы как полезные ископаемые, так и чертежи, чертеж представляет собой программу, в которой подробнейшим образом расписано в какой последовательности и как именно сгруппированы атомы в конечном продукте. Для оптимизации размера такие программы применяют фрактальные вычисления.\nВыберите \"завод\" на поверхности, на панели слева зайдите в закладку \"Использовать\" и в выпадающем списке выберите \"Геологический зонд\".\nВ таблице отмечены материалы, которые необходимы для постройки зонда.\nМатериалы, которых не хватает, отмечены красным. Необходимо добыть и переработать еще полезных ископаемых, что бы получить необходимое количество материалов.\nЕсли все необходимое присутствует на складе, можно запускать производство. Количество последовательно произведенных устройств зависит от уровня завода, чем выше уровень завода, тем большее количество устройств может быть произведено без вашего вмешательства. Для обеспечения безостановочного производства следует использовать роботов.\n\n<i>Изготовьте геологический зонд</i>\n\n<b>вознаграждение: 2000</b>\n'),(19,2,3000,'19(34) Геологоразведка.\n\nГеологический зонд необходим для исследования поверхности.\nВыберите свободное место на поверхности, в левой панели перейдите в закладку \"усовершенствовать\" и запустите исследование поверхности. После запуска зонда исследуется следующий неисследованный слой.\nМатериалы верхнего слоя расположены пластами и легко определяются визуально, материалы среднего и глубинного слоя расположены точечно и их расположение совершенно случайно.\nДля добычи материалов среднего слоя необходимо использовать шахту. Для добычи материалов глубинного слоя необходимо использовать буровую. На одной единице поверхности может располагаться только одна постройка.\n\n<i>Исследуйте средний или глубинный слой</i>\n\n<b>вознаграждение: 3000</b>\n'),(20,2,2000,'20(34) Сборочный цех\n\nВы прошли вводный курс, теперь вам предоставляется самостоятельно разработать и построить космический челнок. У вас в капсуле есть все необходимые чертежи и макеты. Используйте роботов на добывающих предприятиях, это сэкономит время и позволит накопить ресурсы.\nДля сборки челнока вам понадобится \"Сборочный цех\" постройте его на любой свободной поверхности.\n\n<i>Постройте сборочный цех.</i>\n\n<b>вознаграждение: 2000</b>'),(21,2,0,'21(34) Корабли\n\nТеперь можно запустить все добывающие предприятия, для большей производительности используйте роботов, это позволит вам отвлечься от процесса добычи и заняться производством или войнами.\nВ галактике помимо людей были обнаружены Трититы, которые нападают на корабли и иногда даже перехватывают корабли, выходящие из гиперпространства. Вам необходимо тщательно следить и своевременно уничтожать Трититов, иначе от этого могут пострадать ваши торговые корабли, не обладающие оружием.\n\n<i>Запустите все добывающие предприятия и перейдите во вкладку \"корабли\"</i>\n'),(22,3,0,'22(34) Расконсервация\n\nВ списке кораблей вы можете найти несколько патрульных катеров, сейчас эти космические корабли представляют собой сборочные модули, выделите и выберете в списке приказов \"Расконсервировать\" это позволит запустить процесс автоматической сборки корабля. В результате вы получите настоящие рабочие корабли.\nКорабли можно расконсервировать по одному, а можно сразу все, выбрав на главном экране количество кораблей для расконсервации.\n\n<i>Расконсервируйте все патрульные корабли</i>\n'),(23,3,0,'23(34) Флот\n\nТеперь вам надо объединить корабли во флот, что бы ими было легче управлять. Для этого выделите несколько кораблей в списки (для этого воспользуйтесь клавишей Ctrl или Shift) после выделения больше одного корабля появится возможность объединить их в один флот.\n\n<i>Объедините корабли в флот</i>'),(24,3,0,'24(34) Орбита\n\nЕдиным флотом вам необходимо вывести корабль на орбиту для этого выделите флот и отдайте приказ \"Выйти на орбиту\"\n\n<i>Выведите флот на орбиту</i>'),(25,3,0,'25(34) Открытый космос\n\nНа патрульном корабле установлен радар, позволяющий находить в системе чужие корабли. Чтобы воспользоваться этим радаром, вам необходимо отвести корабль от источников гравитационного поля, для этого улетите в сторону от планеты, в любую пустую точку пространства.\n\n<i>Отлетите вашим флотом в сторону от планет</i>\n'),(26,3,0,'26(34) Трититы\n\nВ списке приказов флота выберите \"Переместится в системе\", теперь на карте вы увидите один или несколько желтых кружков, именно так радар отмечает чужие корабли. Если вы не обнаружили таких отметок на планетарной карте, подождите, в среднем каждые 15 минут в звездную систему наведываются Трититы.\n\n<i>Найдите и уничтожьте Трититов</i>'),(27,3,0,'27(34) Шатл\n\nВы справились с этим заданием, теперь можете вернуться на планету и продолжить постройку Шатла\n\n<i>Постройте свой шатл</i>'),(28,2,0,'28(34) Корабли\n\nВы изготовили свой первый космический корабль.\nНа планетарных шатлах установлены только антигравитационные двигатели, которые позволяют взлететь с планеты, для перемещения дальше орбиты необходимы корабли с межпланетными двигателями. Все корабли изготавливаются в законсервированном виде, это позволяет загружать их в транспортные корабли и перемещать как груз. Для использования корабля его необходимо расконсервировать. Процесс расконсервации доступен в меню \"корабли\"\n\n<i>Перейдите в меню управления кораблями</i>'),(29,3,0,'29(34) Расконсервация шатла\n\nВ данном меню осуществляется все управление кораблями.\nДля начала найдите свой шатл и расконсервируйте корабль, что бы стало доступно управление кораблем.\n\n<i>Расконсервируйте шатл</i>'),(30,3,500,'30(34) Первый полет\n\nТеперь можно воспользоваться кораблем и подняться на орбиту. Можно отправить корабль самостоятельно, можно выступить в роли капитана. Функциональность корабля не зависит от наличия капитана на борту, однако нельзя удаленно управлять постройками и торговлей.\nДля того, что бы переместится в корабль необходимо выбрать корабль и отдать приказ \"переместиться в корабль\". В ответ рядом с кораблем появится символ \"*\", что означает наличие капитана корабля.\nДля взлета необходимо немного времени (примерно 10 секунд) после того, как вы отдадите приказ на взлет, с поверхности планеты рядом с кораблем появится таймер, он показывает оставшееся время для выполнения приказа.\n\n<i>Переместитесь в корабль и поднимитесь на орбиту</i>\n\n<b>вознаграждение: 500</b>\n'),(31,3,0,'31(34) Торговая станция\n\nПоздравляем вас с первым выходом в космос в роли капитана корабля.\nПерейдите на вкладку \"Местность\" и посмотрите на планету из космоса. На орбите есть несколько \"точек стояния\", в которых могут быть расположены различные спутники, орбитальные заводы, газодобывающие заводы и другие орбитальные объекты.\nС момента начала колонизации планеты на орбите расположена торговая станция. Постройка служит, прежде всего, защитным сооружением предоставленным конфедерацией. Любой корабль попытавшийся напасть на вашу \"родную\" планету будет моментально уничтожен.\nИсходя из названия понятно, что торговая станция осуществляет еще и торговую функцию. В настоящий момент на торговой станции расположены дополнительные чертежи и макет \"Большого шатла\", данный корабль значительно более вместительный по сравнению с малым шатлом. Необходимо доставить эти чертежи на поверхность. Для стыковки необходимо выделить точку стояния, где находится торговая станция и в левой панели во вкладке \"использовать\" начать стыковку.\n\n<i>Пристыкуйтесь к торговой станции</i>\n'),(32,3,0,'32(34) Склад\n\nДобро пожаловать на станцию.\nНа станции хранятся чертежи и макет, их необходимо переместить на планету, это позволит изготавливать межпланетный шатл. Для управления грузом перейдите в меню Склад.\n\n<i>Перейдите в меню склад</i>'),(33,4,0,'33(34) Чертежи и макеты\n\nМеню Склад позволяет перемещать товары и собственность игрока.\nСлева вверху отображаются все активные корабли игрока, под кораблями все склады, с которыми соотносится выбранный корабль. Это могут быть станции, планеты, соседние корабли, находящиеся в том же месте.\nСправа вверху отображаются окно товаров этого корабля. Если ваш корабль все еще находится на станции, выберите его в левой верхней панели, а в нижней выберите станцию. Справа внизу вы увидите список товаров для \"переноса\". Направление переноса определяется выбранным товаром и стрелкой. Вам необходимо перенести все чертежи и макет со склада станции на корабль.\n\n<i>Перенесите все чертежи и макет на корабль</i>\n'),(34,4,3000,'Вы закончили обучение.\n\nТеперь можно отстыковаться от станции и лететь на планету. Прилетев на планету, не забудьте выгрузить товар на склад.\nПосле этого в выпадающем списке на заводе появятся новые устройства, к которым есть чертежи, а в выпадающем списке сборочного цеха появится новый корабль \"Межпланетный шатл\" макет которого вы привезете.\n\nДля более быстрого развития Конфедерация выплачивает вам 10 конфедерат.\n\n<i>Летите на планету и выгрузите чертежи и макет<i>\n\n<b>вознаграждение: 3000</b>');
