INSERT INTO `users_messages` (`id`, `readed`, `msg_date`, `type`, `to_user`, `from_user`, `hash`, `text`) VALUES (6,0,'2026-08-03 14:48:19',20,1,1,'','На ваш игровой счет зачислено 1500 конфедератов, это процент от зачисления одного из ваших рефералов.'),(7,1,'2026-08-04 06:17:52',20,16,1,'515edd033056241227d5bb6441c4f6da','Доклад министерств и ведомств от 0000-00-00 00:00:00\n\nЗа время вашего отсутствия были получены следующие сообщения:\nВ период с 0000-00-00 00:00:00 по 0000-00-00 00:00:00 получено 2 сообщений: Астрономы зафиксировали излучение, по частоте совпадающее с орудийными выстрелами. Излучение исходит из системы <font color=\"#FF0000\">Раксксла (0:2) точка -398:69</font>.\n\n\nВы получили только 10% сообщений. Чтобы получать больше сообщений, изучите навык Астроном.'),(5,1,'2026-08-03 14:48:19',20,16,1,'','На ваш игровой счет зачислено 15000 конфедератов.'),(1,1,'2026-08-03 12:03:01',20,16,1,'','ВНИМАНИЕ !!! Зафиксирован несанкционированный доступ к складу торговой станции. Согласно записи стерео наблюдения это был дед в красной шубе. Способ проникновения остался неизвестен.'),(2,1,'2026-08-03 12:03:01',20,16,2,'','Привет, это Дед Мороз, индейцы Майа так меня перепугали, что пока в бункер, пока обратно - не успел я на новый год к тебе, но попутно нашел другой календарь, где новый год значится сегодня. Собственно подарок я принес как пологается, не серчай на Деда за опоздание.\n\nPS:подарок лежит на станции, распаковать сможешь на планете, надеюсь он тебе понравится.\nДед Мороз.'),(3,0,'2026-08-03 12:03:01',20,17,1,'','ВНИМАНИЕ !!! Зафиксирован несанкционированный доступ к складу торговой станции. Согласно записи стерео наблюдения это был дед в красной шубе. Способ проникновения остался неизвестен.'),(4,0,'2026-08-03 12:03:01',20,17,2,'','Привет, это Дед Мороз, индейцы Майа так меня перепугали, что пока в бункер, пока обратно - не успел я на новый год к тебе, но попутно нашел другой календарь, где новый год значится сегодня. Собственно подарок я принес как пологается, не серчай на Деда за опоздание.\n\nPS:подарок лежит на станции, распаковать сможешь на планете, надеюсь он тебе понравится.\nДед Мороз.');
